import{_ as t,o as a,c as o,a4 as n}from"./chunks/framework.DCsBdTIw.js";const u=JSON.parse('{"title":"Cline","description":"Complete steps to connect Cline to Tokeness using an OpenAI Compatible provider.","frontmatter":{"title":"Cline","description":"Complete steps to connect Cline to Tokeness using an OpenAI Compatible provider."},"headers":[],"relativePath":"integrations/cline.md","filePath":"integrations/cline.md","lastUpdated":1784332800000}'),i={name:"integrations/cline.md"};function s(l,e,r,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="cline" tabindex="-1">Cline <a class="header-anchor" href="#cline" aria-label="Permalink to &quot;Cline&quot;">​</a></h1><p>Cline supports an OpenAI Compatible provider. Tokeness connects via the OpenAI-compatible endpoint — during configuration you fill in the Base URL, API Key, and Model ID.</p><h2 id="connection-details" tabindex="-1">Connection details <a class="header-anchor" href="#connection-details" aria-label="Permalink to &quot;Connection details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>API Provider</td><td><code>OpenAI Compatible</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.dev/v1</code></td></tr><tr><td>API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Model ID</td><td>Full model name from the Tokeness model marketplace</td></tr></tbody></table><p>If your Cline version does not offer <code>OpenAI Compatible</code>, choose <code>OpenAI</code> and then fill in a custom Base URL.</p><h2 id="_1-prepare-tokeness" tabindex="-1">1. Prepare Tokeness <a class="header-anchor" href="#_1-prepare-tokeness" aria-label="Permalink to &quot;1. Prepare Tokeness&quot;">​</a></h2><p>In the Tokeness console:</p><ol><li>Confirm the wallet balance is available.</li><li>Create an API key dedicated to Cline.</li><li>Go to the model marketplace and copy a model name.</li><li>Open the usage logs — you will use them later to confirm requests.</li></ol><p>You can name the key:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cline-local</span></span></code></pre></div><p>Cline is a coding agent: it reads files, generates code, and retries tasks. Creating a separate key makes it easier to track consumption and troubleshoot issues later.</p><h2 id="_2-open-cline-settings" tabindex="-1">2. Open Cline settings <a class="header-anchor" href="#_2-open-cline-settings" aria-label="Permalink to &quot;2. Open Cline settings&quot;">​</a></h2><p>In VS Code, open the Cline panel and go to the settings page. The common entry point is the settings button in the top right of the Cline panel.</p><p>In the Provider or API Provider dropdown, select:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenAI Compatible</span></span></code></pre></div><p>If the interface only shows an OpenAI option, check whether there is a Base URL, Custom Base URL, or API Base field. As long as you can change the Base URL, you can connect to Tokeness.</p><h2 id="_3-fill-in-the-tokeness-configuration" tabindex="-1">3. Fill in the Tokeness configuration <a class="header-anchor" href="#_3-fill-in-the-tokeness-configuration" aria-label="Permalink to &quot;3. Fill in the Tokeness configuration&quot;">​</a></h2><p>Enter the following:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Base URL: https://n.tokeness.dev/v1</span></span>
<span class="line"><span>API Key: your Tokeness API key</span></span>
<span class="line"><span>Model ID: the model name copied from the Tokeness model marketplace</span></span></code></pre></div><p>Notes:</p><ul><li>Keep the <code>/v1</code> suffix in the Base URL.</li><li>Do not abbreviate the Model ID yourself.</li><li>If Cline offers a Verify, Test, or Save button, verify once before saving.</li><li>If the model list fetch fails, fill in the Model ID manually.</li></ul><h2 id="_4-verification" tabindex="-1">4. Verification <a class="header-anchor" href="#_4-verification" aria-label="Permalink to &quot;4. Verification&quot;">​</a></h2><p>Send a read-only task in Cline:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please read the current project structure, but do not modify any files. Summarize the top-level directories you see.</span></span></code></pre></div><p>Check three things during verification:</p><ol><li>Cline can reply normally.</li><li>A request appears in the Tokeness usage logs.</li><li>The key, model name, and status code in the logs are correct.</li></ol><p>Do not let Cline make large-scale code changes on the first test. First confirm the connection, model, and permissions are all working, then proceed with file-writing tasks.</p><h2 id="_5-settings-before-writing-files" tabindex="-1">5. Settings before writing files <a class="header-anchor" href="#_5-settings-before-writing-files" aria-label="Permalink to &quot;5. Settings before writing files&quot;">​</a></h2><p>Cline performs file reads and modifications. After connecting to Tokeness, tool permissions are still controlled by Cline and VS Code — Tokeness only handles the model calls.</p><p>Check the following before writing files:</p><table tabindex="0"><thead><tr><th>Item</th><th>Action</th></tr></thead><tbody><tr><td>Key</td><td>Use a Cline-dedicated key</td></tr><tr><td>Quota</td><td>Set an appropriate quota on the key</td></tr><tr><td>Model</td><td>Choose a model suited for coding tasks</td></tr><tr><td>Logs</td><td>Keep Tokeness usage logs open and watch for repeated calls</td></tr><tr><td>Git</td><td>Confirm the working tree status before large changes</td></tr></tbody></table><h2 id="_6-troubleshooting" tabindex="-1">6. Troubleshooting <a class="header-anchor" href="#_6-troubleshooting" aria-label="Permalink to &quot;6. Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Verify failed</td><td>Check the Base URL, key, and model name</td></tr><tr><td>401 Unauthorized</td><td>Re-copy the API key and confirm there are no spaces</td></tr><tr><td>404 Not Found</td><td>Base URL should be <code>https://n.tokeness.dev/v1</code></td></tr><tr><td>model not found</td><td>Re-copy the Model ID from the Tokeness model marketplace</td></tr><tr><td>Cline reports errors but no Tokeness logs</td><td>The current provider is not routing through Tokeness</td></tr><tr><td>Replies work but tool calls fail</td><td>Switch to a model with stronger coding ability, or narrow the task scope</td></tr><tr><td>High consumption</td><td>Reduce the context range and use a separate key with a quota</td></tr></tbody></table><h2 id="external-docs" tabindex="-1">External docs <a class="header-anchor" href="#external-docs" aria-label="Permalink to &quot;External docs&quot;">​</a></h2><ul><li><a href="https://docs.cline.bot/provider-config/openai-compatible" target="_blank" rel="noreferrer">Cline OpenAI Compatible Provider</a></li><li><a href="https://docs.cline.bot/provider-config/openai" target="_blank" rel="noreferrer">Cline OpenAI Provider Custom Base URL</a></li></ul>`,35)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
